#include "json.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <map>
#include <vector>
#include <fstream>
#include <set>
#include <iomanip>
#include <openssl/sha.h>
static std::string hash_file(const std::string&path){std::ifstream in(path);std::ostringstream bytes;bytes<<in.rdbuf();auto text=bytes.str();unsigned char hash[SHA256_DIGEST_LENGTH];SHA256(reinterpret_cast<const unsigned char*>(text.data()),text.size(),hash);std::ostringstream out;for(auto c:hash)out<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);return out.str();}
static double median(std::vector<double> v){if(v.empty())throw std::runtime_error("missing samples");std::sort(v.begin(),v.end());size_t n=v.size();return n%2?v[n/2]:(v[n/2-1]+v[n/2])/2;}
using Samples=std::map<std::string,std::map<std::string,std::map<int,std::vector<double>>>>;
#include "analysis_load.hpp"
static void admission(const std::string&path,const std::string&rows,const std::string&binary,const std::string&protocol,const std::string&isolator){auto j=read_json(path);if(j.at("schema").str()!="isolated-bench/1"||j.at("isolation_binary_sha256").str()!=isolator)throw std::runtime_error("isolation binary or schema mismatch");if(j.at("command_binary_sha256").str()!=binary||j.at("protocol_sha256").str()!=protocol)throw std::runtime_error("binary or protocol mismatch");if(j.at("admitted").kind!=Json::Boolean||j.at("contended").kind!=Json::Boolean||j.at("rows_sha256").str()!=hash_file(rows))throw std::runtime_error("receipt binding or types");if(j.at("admitted").value!="true"||j.at("contended").value!="false"||j.at("exit_status").integer()!=0)throw std::runtime_error("wall admission invalid");}
int main(int argc,char**argv){try{std::cout<<std::setprecision(17);if(argc!=6)throw std::runtime_error("analysis CALIBRATION_ROWS CALIBRATION_RECEIPT HELDOUT_ROWS HELDOUT_RECEIPT FROZEN_PROTOCOL");auto protocol=read_json(argv[5]);if(protocol.at("freeze").at("status").str()!="frozen")throw std::runtime_error("unfrozen protocol");std::string digest=protocol.at("freeze").at("protocol_sha256").str(),binary=protocol.at("arms").at(size_t(0)).at("instrument").at("binary_sha256").str();std::string isolator=protocol.at("execution").at("placement").at("isolation_binary_sha256").str();Json body=protocol;body.object.erase("freeze");std::string canonical=canonical_json(body);unsigned char hash[SHA256_DIGEST_LENGTH];SHA256(reinterpret_cast<const unsigned char*>(canonical.data()),canonical.size(),hash);std::ostringstream canonical_hash;for(auto c:hash)canonical_hash<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);if(canonical_hash.str()!=digest)throw std::runtime_error("canonical protocol hash mismatch");admission(argv[2],argv[1],binary,digest,isolator);admission(argv[4],argv[3],binary,digest,isolator);auto calibration=load(argv[1],"calibration"),heldout=load(argv[3],"heldout");for(auto&[curve,arms]:calibration){std::string best_ref,best_candidate;double ref=1e100,candidate=1e100;for(auto&[arm,points]:arms){std::vector<double> vals;for(auto&[index,v]:points)vals.push_back(median(v));double cost=median(vals);if(arm.rfind("window:",0)==0||arm.rfind("openssl-public:",0)==0){if(cost<ref){ref=cost;best_ref=arm;}}if(arm.rfind("maps:",0)==0||arm.rfind("fused:",0)==0){if(cost<candidate){candidate=cost;best_candidate=arm;}}}if(best_ref.empty()||best_candidate.empty())throw std::runtime_error("missing decisive arm");auto&r=heldout.at(curve).at(best_ref);auto&c=heldout.at(curve).at(best_candidate);double aa=1,min_speedup=1e100;std::vector<double>ratios;for(auto&[i,points]:r){auto wm=heldout.at(curve).at(best_ref).at(i);std::string aa_arm=best_ref.rfind("window:",0)==0?"window-aa"+best_ref.substr(6):"openssl-public-aa"+best_ref.substr(14);auto wa=heldout.at(curve).at(aa_arm).at(i);double a=median(wm),b=median(wa);aa=std::max(aa,std::max(a/b,b/a));double ratio=median(points)/median(c.at(i));ratios.push_back(ratio);min_speedup=std::min(min_speedup,ratio);}double threshold=std::max(1.01,aa);bool pass=min_speedup>threshold;std::cout<<"{\"curve\":\""<<curve<<"\",\"reference\":\""<<best_ref<<"\",\"candidate\":\""<<best_candidate<<"\",\"median_point_speedup\":"<<median(ratios)<<",\"minimum_point_speedup\":"<<min_speedup<<",\"aa_envelope\":"<<aa<<",\"acceptance_threshold\":"<<threshold<<",\"supported_on_heldout_panel\":"<<(pass?"true":"false")<<"}"<<std::endl;}return 0;}catch(const std::exception&e){std::cerr<<"analysis refused: "<<e.what()<<std::endl;return 1;}}
